<?php
declare(strict_types=1); namespace App\Controller; use App\Entity\Company; use App\Entity\Job; use App\Entity\User; use Doctrine\ORM\EntityManagerInterface; use Symfony\Bundle\FrameworkBundle\Controller\AbstractController; use Symfony\Component\HttpFoundation\Request; use Symfony\Component\HttpFoundation\Response; use Symfony\Component\Routing\Attribute\Route; use Symfony\Component\Security\Http\Attribute\IsGranted;
#[Route('/company'),IsGranted('ROLE_COMPANY')] final class CompanyController extends AbstractController { private function company(EntityManagerInterface $em):Company{$u=$this->getUser();if(!$u instanceof User)throw $this->createAccessDeniedException();$c=$em->getRepository(Company::class)->findOneBy(['owner'=>$u]);if(!$c)throw $this->createNotFoundException();return $c;} #[Route('/jobs',name:'company_jobs')] public function jobs(EntityManagerInterface $em):Response{return $this->render('company/jobs.html.twig',['jobs'=>$em->getRepository(Job::class)->findBy(['company'=>$this->company($em)],['createdAt'=>'DESC'])]);} #[Route('/jobs/new',name:'company_job_new',methods:['GET','POST'])] public function new(Request $r,EntityManagerInterface $em):Response{$job=(new Job())->setCompany($this->company($em));if($r->isMethod('POST')){if(!$this->isCsrfTokenValid('new-job',(string)$r->request->get('_token')))throw $this->createAccessDeniedException();$job->setTitle((string)$r->request->get('title'))->setDescription((string)$r->request->get('description'))->setContractType((string)$r->request->get('contractType','CDI'))->setLocation($r->request->get('location'))->setRemote($r->request->getBoolean('remote'))->setPublished($r->request->getBoolean('published'));$em->persist($job);$em->flush();return $this->redirectToRoute('company_jobs');}return $this->render('company/new.html.twig',['job'=>$job]);} }
